# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from hourglass.errors import ProjectError
from hourglass.schedule import worker_minutes

def _check(shifts):
    if not shifts:
        raise ProjectError("no shifts to report")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("shift has no worker")

def _counts(shifts):
    counts = {}
    for shift in shifts:
        prior = counts.get(shift.worker, 0)
        counts[shift.worker] = prior + 1
    return counts

def _ranked(mins):
    names = sorted(mins)
    return sorted(names, key=lambda name: -mins[name])

def _line(name, counts, mins):
    hours = mins[name] / 60
    return f"{name}: {counts[name]} shifts, {hours:.1f} h"

def timesheet_lines(shifts):
    """One line per worker, busiest first."""
    shifts = list(shifts)
    _check(shifts)
    counts = _counts(shifts)
    mins = worker_minutes(shifts)
    order = _ranked(mins)
    return [_line(name, counts, mins) for name in order]
